CREATE FUNCTION public.require_chat_actor(actor uuid, tenant uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' OR actor IS NULL OR tenant IS NULL
        OR cardinality(public.knowledge_actor_roles(actor, tenant, 'ai.chat')) = 0 THEN
        RAISE EXCEPTION 'Chat permission required' USING ERRCODE = '42501';
    END IF;
END;
$$;

CREATE FUNCTION public.chat_turn_view(item public.chat_turns) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    RETURN jsonb_build_object('turn_id', item.client_turn_id, 'conversation_id', item.conversation_id,
        'state', item.state, 'retryable', item.state = 'failed' OR
            (item.state = 'processing' AND item.lease_until <= clock_timestamp()),
        'retry_after_seconds', CASE WHEN item.state = 'processing'
            THEN greatest(0, ceil(extract(epoch FROM item.lease_until - clock_timestamp()))::integer) ELSE 0 END,
        'request', jsonb_build_object('turn_id', item.client_turn_id, 'user_query', item.request_query,
            'institution_id', item.institution_id, 'conversation_id', item.conversation_id,
            'session_id', item.session_id, 'resource_id', item.knowledge_source_id),
        'response', item.response);
END;
$$;
-- SOURCE read.sql sha256=91aef81a48e57d43b026d84583f848fb52b546fbd1326f5c28b7ae0c3303b873
CREATE FUNCTION public.read_chat_turn(actor uuid, tenant uuid, selected_turn uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE item public.chat_turns; conversation public.conversations;
BEGIN
    PERFORM public.require_chat_actor(actor, tenant);
    SELECT * INTO item FROM public.chat_turns t
        WHERE t.actor_id = actor AND t.client_turn_id = selected_turn AND t.institution_id = tenant;
    IF NOT FOUND THEN RAISE EXCEPTION 'Chat turn not found' USING ERRCODE = 'P0002'; END IF;
    SELECT * INTO conversation FROM public.conversations c
        WHERE c.conversation_id = item.conversation_id AND c.user_id = actor AND c.chat_institution_id = tenant;
    IF NOT FOUND THEN RAISE EXCEPTION 'Chat turn not found' USING ERRCODE = 'P0002'; END IF;
    IF conversation.knowledge_source_id IS NOT NULL THEN
        BEGIN
            PERFORM public.read_resource_chat_context(actor, tenant, conversation.knowledge_source_id);
        EXCEPTION WHEN no_data_found THEN
            RAISE EXCEPTION 'Source access changed' USING ERRCODE = '40001';
        END;
    END IF;
    IF item.state = 'completed' AND NOT public.check_knowledge_policy(actor, item.knowledge_policy) THEN
        RAISE EXCEPTION 'Source access changed' USING ERRCODE = '40001';
    END IF;
    RETURN public.chat_turn_view(item);
END;
$$;
-- SOURCE claim.sql sha256=f0227a175e960b97bae08e155e8e29dd30dfadd7b05cc9221664813f497097cb
CREATE FUNCTION public.claim_chat_turn(actor uuid, tenant uuid, selected_turn uuid,
    selected_conversation uuid, selected_session uuid, query text, resource_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE item public.chat_turns; conversation public.conversations; source_id uuid;
    message_id uuid := gen_random_uuid(); sequence integer;
BEGIN
    PERFORM public.require_chat_actor(actor, tenant);
    IF selected_turn IS NULL OR selected_conversation IS NULL OR selected_session IS NULL
        OR query IS NULL OR length(btrim(query)) NOT BETWEEN 1 AND 4000 THEN
        RAISE EXCEPTION 'Invalid turn request' USING ERRCODE = '22023';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('chat-turn:' || actor::text || ':' || selected_turn::text, 0));
    SELECT * INTO item FROM public.chat_turns t WHERE t.actor_id = actor AND t.client_turn_id = selected_turn FOR UPDATE;
    IF FOUND AND (item.institution_id <> tenant OR item.conversation_id <> selected_conversation
        OR item.request_query <> query OR item.session_id <> selected_session) THEN
        RAISE EXCEPTION 'Turn identifier was used for another request' USING ERRCODE = '22023';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('chat-conversation:' || selected_conversation::text, 0));
    SELECT * INTO conversation FROM public.conversations c WHERE c.conversation_id = selected_conversation FOR UPDATE;
    IF FOUND THEN
        IF conversation.user_id <> actor OR (conversation.chat_institution_id IS NOT NULL AND conversation.chat_institution_id <> tenant) THEN
            RAISE EXCEPTION 'Conversation not found' USING ERRCODE = 'P0002';
        END IF;
        IF conversation.status <> 'active' OR (resource_id IS NOT NULL AND resource_id IS DISTINCT FROM conversation.knowledge_source_id) THEN
            RAISE EXCEPTION 'Conversation scope changed' USING ERRCODE = '40001';
        END IF;
        source_id := conversation.knowledge_source_id;
    ELSE
        source_id := resource_id;
    END IF;
    IF source_id IS NOT NULL THEN PERFORM public.read_resource_chat_context(actor, tenant, source_id); END IF;
    IF item.client_turn_id IS NOT NULL THEN
        IF source_id IS DISTINCT FROM item.knowledge_source_id THEN
            RAISE EXCEPTION 'Turn resource changed' USING ERRCODE = '22023';
        END IF;
        IF item.state = 'completed' OR (item.state = 'processing' AND item.lease_until > clock_timestamp()) THEN
            RETURN public.read_chat_turn(actor, tenant, selected_turn);
        END IF;
        UPDATE public.chat_turns SET state = 'processing', worker_token = gen_random_uuid(),
            lease_until = clock_timestamp() + interval '5 minutes', attempts = attempts + 1, updated_at = clock_timestamp()
            WHERE actor_id = actor AND client_turn_id = selected_turn RETURNING * INTO item;
    ELSE
        IF EXISTS (SELECT 1 FROM public.chat_turns t WHERE t.conversation_id = selected_conversation AND t.state <> 'completed') THEN
            RAISE EXCEPTION 'Recover the unfinished turn first' USING ERRCODE = 'PT409';
        END IF;
        IF conversation.conversation_id IS NULL THEN
            INSERT INTO public.conversations(conversation_id, user_id, title, knowledge_source_id, resource_institution_id, chat_institution_id)
                VALUES(selected_conversation, actor, left(query, 60), source_id, CASE WHEN source_id IS NOT NULL THEN tenant END, tenant);
        ELSIF conversation.chat_institution_id IS NULL THEN
            UPDATE public.conversations SET chat_institution_id = tenant WHERE conversation_id = selected_conversation;
        END IF;
        SELECT COALESCE(max(m.message_sequence), 0) + 1 INTO sequence FROM public.messages m WHERE m.conversation_id = selected_conversation;
        INSERT INTO public.chat_turns(actor_id, client_turn_id, institution_id, conversation_id, session_id, knowledge_source_id,
            request_query, user_message_id, user_sequence, state, worker_token, lease_until)
        VALUES(actor, selected_turn, tenant, selected_conversation, selected_session, source_id, query, message_id, sequence,
            'processing', gen_random_uuid(), clock_timestamp() + interval '5 minutes') RETURNING * INTO item;
        INSERT INTO public.messages(message_id, conversation_id, message_sequence, message_type, content_text)
            VALUES(message_id, selected_conversation, sequence, 'user', query);
    END IF;
    UPDATE public.conversations SET updated_at = clock_timestamp() WHERE conversation_id = selected_conversation;
    RETURN public.chat_turn_view(item) || jsonb_build_object('state', 'claimed', 'worker_token', item.worker_token,
        'user_sequence', item.user_sequence);
END;
$$;
-- SOURCE complete.sql sha256=7d1542468d7813e9b7eae278df4a2caa742177afaa4d684501373a1aaea55a1b
CREATE FUNCTION public.complete_chat_turn(actor uuid, tenant uuid, selected_turn uuid, token uuid,
    reply jsonb, policy jsonb, details jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE item public.chat_turns; assistant uuid := gen_random_uuid(); response_id uuid; operation_id uuid;
    chunk jsonb; citation jsonb; rank integer := 0; receipt jsonb;
BEGIN
    PERFORM public.require_chat_actor(actor, tenant);
    PERFORM pg_advisory_xact_lock(hashtextextended('chat-turn:' || actor::text || ':' || selected_turn::text, 0));
    SELECT * INTO item FROM public.chat_turns t
        WHERE t.actor_id = actor AND t.client_turn_id = selected_turn AND t.institution_id = tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Chat turn not found' USING ERRCODE = 'P0002'; END IF;
    IF item.state <> 'processing' OR token IS NULL OR item.worker_token IS DISTINCT FROM token THEN
        RAISE EXCEPTION 'Turn worker was replaced' USING ERRCODE = 'PT410';
    END IF;
    PERFORM 1 FROM public.conversations c WHERE c.conversation_id = item.conversation_id FOR UPDATE;
    IF NOT public.check_knowledge_policy(actor, policy) OR policy->>'institution_id' IS DISTINCT FROM tenant::text THEN
        RAISE EXCEPTION 'Source access changed' USING ERRCODE = '40001';
    END IF;
    IF item.knowledge_source_id IS NOT NULL THEN
        PERFORM public.read_resource_chat_context(actor, tenant, item.knowledge_source_id);
        IF (SELECT array_agg(key) FROM jsonb_object_keys(policy->'sources') key) IS DISTINCT FROM ARRAY[item.knowledge_source_id::text] THEN
            RAISE EXCEPTION 'Resource policy mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF reply->>'status' IS NULL OR reply->>'status' NOT IN ('success', 'insufficient_context')
        OR reply->>'conversation_id' IS DISTINCT FROM item.conversation_id::text
        OR reply->>'session_id' IS DISTINCT FROM item.session_id::text
        OR (reply->>'status' = 'success' AND NULLIF(btrim(reply->>'answer'), '') IS NULL)
        OR (reply->>'status' = 'insufficient_context' AND reply->>'answer' IS NOT NULL) THEN
        RAISE EXCEPTION 'Invalid answer receipt' USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.messages(message_id, conversation_id, message_sequence, message_type, content_text, knowledge_policy)
    VALUES(assistant, item.conversation_id, item.user_sequence + 1, 'assistant',
        COALESCE(reply->>'answer', 'The available knowledge is insufficient to answer this question.'), policy);
    INSERT INTO public.ai_responses(message_id, provider_name, model_name, validation_status, input_token_count, output_token_count, latency_ms)
    VALUES(assistant, 'openrouter', COALESCE(NULLIF(details->>'model_name', ''), 'unspecified'), 'pending',
        (details->>'input_tokens')::integer, (details->>'output_tokens')::integer, (details->>'latency_ms')::integer)
    RETURNING ai_response_id INTO response_id;
    INSERT INTO public.retrieval_operations(ai_response_id, query_text, status, result_count, completed_at)
    VALUES(response_id, COALESCE(NULLIF(details->>'retrieval_query', ''), item.request_query), 'completed',
        jsonb_array_length(details->'chunks'), clock_timestamp()) RETURNING retrieval_operation_id INTO operation_id;
    FOR chunk IN SELECT * FROM jsonb_array_elements(details->'chunks') LOOP
        rank := rank + 1;
        IF NOT EXISTS (SELECT 1 FROM public.knowledge_chunks c
            JOIN public.document_processing_runs run USING(processing_run_id)
            JOIN public.document_versions v USING(document_version_id)
            JOIN public.documents d USING(document_id)
            WHERE c.chunk_id = (chunk->>'chunk_id')::uuid
                AND policy->'versions'->>v.document_version_id::text = d.knowledge_source_id::text) THEN
            RAISE EXCEPTION 'Chunk outside answer policy' USING ERRCODE = '23514';
        END IF;
        INSERT INTO public.retrieved_chunks(retrieval_operation_id, chunk_id, retrieval_rank, relevance_score, selected_for_context)
        VALUES(operation_id, (chunk->>'chunk_id')::uuid, rank, (chunk->>'score')::numeric, true);
    END LOOP;
    rank := 0;
    FOR citation IN SELECT * FROM jsonb_array_elements(reply->'source_references') LOOP
        rank := rank + 1;
        IF NOT EXISTS (SELECT 1 FROM public.retrieved_chunks c WHERE c.retrieval_operation_id = operation_id
            AND c.chunk_id = (citation->>'chunk_id')::uuid) THEN
            RAISE EXCEPTION 'Citation outside retrieved evidence' USING ERRCODE = '23514';
        END IF;
        INSERT INTO public.message_citations(message_id, retrieval_operation_id, chunk_id, display_order)
        VALUES(assistant, operation_id, (citation->>'chunk_id')::uuid, rank);
    END LOOP;
    receipt := reply || jsonb_build_object('message_id', assistant, 'model_used', NULL, 'metadata', '{}'::jsonb);
    UPDATE public.chat_turns SET state = 'completed', assistant_message_id = assistant, response = receipt,
        knowledge_policy = policy, updated_at = clock_timestamp() WHERE actor_id = actor AND client_turn_id = selected_turn;
    UPDATE public.conversations SET updated_at = clock_timestamp() WHERE conversation_id = item.conversation_id;
    RETURN public.read_chat_turn(actor, tenant, selected_turn);
END;
$$;

CREATE FUNCTION public.fail_chat_turn(actor uuid, tenant uuid, selected_turn uuid, token uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    PERFORM public.require_chat_actor(actor, tenant);
    UPDATE public.chat_turns SET state = 'failed', updated_at = clock_timestamp()
        WHERE actor_id = actor AND client_turn_id = selected_turn AND institution_id = tenant
            AND worker_token = token AND state = 'processing';
END;
$$;
